<script setup lang="ts">
import WorkspaceTopbar from '../../shared/WorkspaceTopbar.vue';
import MaterialImportSection from '../import/MaterialImportSection.vue';
import RecordingTranscription from '../recording/RecordingTranscription.vue';
import LiveTranscript from '../recording/LiveTranscript.vue';import {useLiveSubtitles} from '../recording/useLiveSubtitles';
import {computed,ref,watch,onMounted,onUnmounted,nextTick} from 'vue';import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router';import {useApplication} from '../../application';import {useMeetingCreateFlow} from './useMeetingCreateFlow';import MeetingInfoDrawer from './MeetingInfoDrawer.vue';import MeetingInfoEditor from './MeetingInfoEditor.vue';import Icon from '../../shared/Icon.vue';import LegacyRecordingFiles from '../recording/LegacyRecordingFiles.vue';import RecordingArchivePlayback from '../recording/RecordingArchivePlayback.vue';
onBeforeRouteUpdate(()=>!(busy.value&&parts.value.length>0)&&!materialsState.value.closeBlocked);
const recordingTranscriptionRef=ref<InstanceType<typeof RecordingTranscription>>();onBeforeRouteLeave(()=>busy.value||materialsState.value.closeBlocked?false:recordingTranscriptionRef.value?.beforeLeave()??true);
const localDevelopment=import.meta.env.DEV&&import.meta.env.VITE_LOCAL_DEV_LOGIN==='1';
const app=useApplication(),{session,pcmRecorder:native,create,recordingApi}=app,route=useRoute(),router=useRouter();const infoEditorRef=ref<InstanceType<typeof MeetingInfoEditor>>();function closeInfo(){if(infoEditorRef.value?.cancel?.()??true)infoOpen.value=false;}
const materialsDialog=ref<HTMLDialogElement>(),materialsOpen=ref(false),materialsState=ref({busy:false,blocked:false,failed:false,hasFiles:false,closeBlocked:false});
async function openMaterials(){if(!meeting.value||!actor())return;materialsOpen.value=true;await nextTick();materialsDialog.value?.showModal();}
function closeMaterials(){if(materialsState.value.closeBlocked)return false;materialsDialog.value?.close();materialsOpen.value=false;return true;}
const infoOpen=ref(false),interruptDialog=ref<HTMLDialogElement>(),endDialog=ref<HTMLDialogElement>(),busy=ref(false),localError=ref<string|null>(null),endError=ref<string|null>(null),lastEnd=ref<'save'|'process'|null>(null),live=ref<HTMLElement>();
const actor=()=>session.current.value?.actor.enterpriseId??null,meeting=computed(()=>native.meetingId.value),active=computed(()=>native.phase.value==='RECORDING'),paused=computed(()=>native.phase.value==='PAUSED'),saving=computed(()=>busy.value||['SAVING','AUTHORIZING'].includes(native.phase.value)),failed=computed(()=>native.phase.value==='ERROR'),finished=computed(()=>native.record.value?.finished??false);
const parts=computed(()=>native.record.value?.parts.map((p,index)=>({id:p.partId,index:index+1,name:'录音片段 '+String(index+1).padStart(2,'0'),bytes:p.sampleCount*2,chunks:Array.from({length:p.finalSequence},(_,n)=>n+1),elapsedMs:p.sampleCount/16,savedElapsedMs:p.sampleCount/16,incomplete:false,state:index===native.record.value!.parts.length-1?(active.value?'RECORDING':paused.value?'PAUSED':finished.value?'SAVED':'INTERRUPTED'):'INTERRUPTED'}))??[]),savedParts=computed(()=>parts.value.filter(p=>p.bytes>0&&!['RECORDING','PAUSED'].includes(p.state)));
const subtitleParts=computed(()=>{let samples=0;return(native.record.value?.parts??[]).map((part,index)=>{const value={partId:part.partId,partNo:index+1,startMs:Math.floor(samples/16)};samples+=part.sampleCount;return value;});});
const r={...native},interrupted=computed(()=>!active.value&&!paused.value&&parts.value.length>0&&!finished.value),state=computed(()=>saving.value?'保存中':failed.value?'需要恢复保存':active.value?'录音中':paused.value?'已暂停':finished.value?'已结束采集':interrupted.value?'本段已中断':'等待麦克风授权');const label=computed(()=>failed.value?'重试保存':active.value?'暂停录音':paused.value?'继续录音':parts.value.length?'开始下一段':'重新授权并开始'),transcriptStatus=computed(()=>paused.value?'已暂停，内容保留':interrupted.value?'已中断，内容保留':'当前累计内容'),saveStatus=computed(()=>native.pendingCount.value?`${native.pendingCount.value} 个分片待服务端确认`:finished.value?'采集已封存，归档状态见下方':parts.value.some(p=>p.bytes>0)?'分片已获服务端保存确认':'等待录音数据');
const pageMounted=ref(false);
const subtitles=useLiveSubtitles(app.subtitleApi,{actor,meeting:()=>meeting.value,sessionId:()=>native.record.value?.session.sessionId??null,eligible:()=>pageMounted.value&&!!actor()&&!!native.record.value});
const stopSubtitles=watch(()=>[pageMounted.value,actor(),meeting.value,native.record.value?.session.sessionId],()=>subtitles.synchronize(),{immediate:true,flush:'sync'});
function clock(ms:number){const t=Math.floor(Math.max(0,ms)/1000);return `${String(Math.floor(t/3600)).padStart(2,'0')}:${String(Math.floor(t/60)%60).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;}
const flow=useMeetingCreateFlow(create,actor,async id=>{await native.attach(id);await router.replace('/recording/'+id);app.setMeetingScope(id);return router.currentRoute.value.path==='/recording/'+id;});
async function initialize(){if(!actor())return;const id=typeof route.params.id==='string'?route.params.id:null;if(id){await native.attach(id);app.setMeetingScope(id);return;}const old=native.record.value??await native.restore();if(old&&!old.finished){await router.replace('/recording/'+old.meetingId);app.setMeetingScope(old.meetingId);}}
async function start(){if(busy.value||finished.value)return;busy.value=true;localError.value=null;try{await initialize();if(!meeting.value){await flow.open();if(flow.error.value)throw flow.error.value;}if(!meeting.value)throw Error('会议创建尚未确认，请重试原请求');await native.start();}catch(cause){localError.value=cause instanceof Error?cause.message:'无法开始录音';}finally{busy.value=false;}}
async function primary(){if(busy.value)return;localError.value=null;try{if(failed.value){await native.retry();return;}if(active.value){await native.pause();return;}if(paused.value){await native.resume();return;}await start();}catch(cause){localError.value=cause instanceof Error?cause.message:'录音操作尚未完成';}}
async function reconnect(){busy.value=true;localError.value=null;try{await native.reconnect();}catch(cause){localError.value=cause instanceof Error?cause.message:'恢复上传尚未完成';}finally{busy.value=false;}}
async function interrupt(){const who=actor(),id=meeting.value;if(!who||busy.value)return;busy.value=true;localError.value=null;try{await native.interrupt();if(who===actor()&&id===meeting.value)interruptDialog.value?.close();}catch(cause){if(who===actor()&&id===meeting.value)localError.value=cause instanceof Error?cause.message:'本段保存未完成';}finally{busy.value=false;}}
async function end(){const who=actor(),id=meeting.value;if(!who||busy.value)return;try{if(active.value)await native.pause();if(who!==actor()||id!==meeting.value)return;lastEnd.value=null;endError.value=null;endDialog.value?.showModal();}catch(cause){if(who===actor()&&id===meeting.value)localError.value=cause instanceof Error?cause.message:'暂停未确认，请保留当前页面';}}
async function finish(action:'save'|'process'){const who=actor(),id=meeting.value;if(!who||busy.value)return;busy.value=true;lastEnd.value=action;endError.value=null;try{await native.finish();if(who!==actor()||id!==meeting.value)return;busy.value=false;endDialog.value?.close();if(action==='process')await router.push({path:'/meeting/'+id+'/processing',query:{transcribe:'1'}});else await router.push('/meetings');}catch(cause){if(who===actor()&&id===meeting.value)endError.value=cause instanceof Error?cause.message:'服务端保存尚未确认，请恢复上传后重试';}finally{busy.value=false;}}
function closeDecision(dialog:HTMLDialogElement|undefined){if(busy.value)return false;dialog?.close();return true;}
function resetPrivateDialogs(){interruptDialog.value?.close();endDialog.value?.close();materialsDialog.value?.close();materialsOpen.value=false;infoOpen.value=false;localError.value=null;endError.value=null;lastEnd.value=null;}
watch(()=>[actor(),meeting.value],resetPrivateDialogs,{flush:'sync',immediate:true});
let initializing:Promise<void>|null=null;async function load(){if(initializing)return initializing;initializing=initialize();try{await initializing;}catch(cause){localError.value=cause instanceof Error?cause.message:'录音记录暂不可用';}finally{initializing=null;}}
const stop=watch(()=>[actor(),route.params.id],()=>{if(actor())void load();},{immediate:true});onMounted(async()=>{pageMounted.value=true;if(!session.current.value)try{await session.refresh();}catch{/* Existing session feedback handles identity loss. */}await load();if(route.query.start==='1'){await router.replace({path:route.path,query:{}});await start();}});onUnmounted(()=>{stopSubtitles();subtitles.dispose();stop();flow.dispose();});
</script>
<template><div class="layout"><div class="main"><WorkspaceTopbar/><main class="content"><div class="ac-page acr-page"><header class="page-head"><div class="ac-workspace-leading"><button class="btn ac-workspace-back" type="button" aria-label="返回会议列表" title="返回会议列表" @click="router.push('/meetings')"><Icon name="arrowL" :size="18"/></button><div><h1 class="page-title">在线录音</h1><div class="page-desc">在线录音并实时转写，站内切换不影响录音，可继续处理其他工作。请保持当前标签页打开，刷新、关闭标签页或退出浏览器将中断录音。</div></div></div></header>
 <section class="card acr-record-card" aria-label="会议录音"><div class="acr-record-top"><div class="acr-record-symbol" :class="active?'is-recording':'is-paused'"><Icon name="mic" :size="30"/><span></span></div><div class="acr-record-time"><strong id="ac-record-clock">{{clock(r.partElapsed.value)}}</strong><span id="ac-record-status">第{{parts.at(-1)?.index??1}}段 · {{state}}</span><small class="muted">累计录音 <time id="ac-record-total">{{clock(r.elapsed.value)}}</time></small></div><div class="acr-record-controls"><button class="acr-icon-button" :aria-label="label" :title="label" :disabled="saving||finished||!session.current.value" @click="primary"><Icon :name="failed?'refresh':active?'pause':'play'" :size="20"/></button><span class="acr-interrupt-slot"><button v-if="active||paused||saving" class="btn sm ghost" :disabled="saving||failed" @click="interruptDialog?.showModal()">中断本段</button></span><button class="acr-icon-button acr-stop" aria-label="结束录音" title="结束录音" :disabled="saving||failed||finished||!parts.length" @click="end"><svg width="19" height="19" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><rect x="5" y="5" width="14" height="14" rx="2"/></svg></button></div></div>
 <div class="acr-record-save small muted">本次已采集 {{parts.reduce((n,p)=>n+p.chunks.length,0)}} 个音频分片 · 保存范围约至 {{clock(parts.reduce((n,p)=>n+p.savedElapsedMs,0))}} · {{saveStatus}}</div><div v-if="savedParts.length" class="acr-saved-parts" aria-label="已记录录音段"><span class="acr-parts-caption">已记录录音 · {{savedParts.length}}段</span><div class="acr-saved-part-files"><div v-for="part in savedParts" :key="part.id" class="acr-saved-part"><Icon name="file" :size="12"/><span>第{{part.index}}段 · {{part.name}}</span><time>{{clock(part.elapsedMs)}}</time><small :title="part.incomplete?'仅保留可恢复范围，尾段可能缺失':''">{{part.state==='SYSTEM_INTERRUPTED'?'系统中断':part.state==='INTERRUPTED'?'中断保存':part.state==='SAVED'?'结束保存':'已保存'}}{{part.incomplete?' · 范围不完整':''}}</small></div></div></div>
 <div class="acr-record-feedback"><div v-if="localError||r.error.value" class="ac-error" role="alert">{{localError??r.error.value}}</div><div v-else-if="!active&&!paused&&parts.length&&!finished" class="small muted acr-interruption-note">本段已保存，可开始下一段。</div><div v-if="!parts.length" class="small muted acr-interruption-note">请允许麦克风权限并检查设备。<RouterLink to="/meetings" class="btn sm ghost">改为导入文件</RouterLink></div></div><div v-if="native.pendingCount.value" class="between mt12"><span class="small muted">未确认音频 {{native.pendingCount.value}} 个分片</span><button class="btn sm" :disabled="busy" @click="reconnect">恢复上传</button></div><div class="acr-subtle-tools"><button class="acr-tool" :disabled="!meeting" @click="infoOpen=true"><Icon name="edit" :size="14"/> 填写会议信息</button><span></span><button class="acr-tool" :disabled="!meeting" @click="openMaterials"><Icon name="file" :size="14"/> 添加背景资料</button></div></section>
 <section class="card acr-transcript-card"><div class="card-h"><div class="card-t">实时转写</div><span class="small muted">全部录音段 · {{transcriptStatus}}</span><button class="acr-tool ml-a" title="读取最新字幕并滚动到底部" @click="subtitles.refresh();live?.scrollTo({top:live.scrollHeight,behavior:'smooth'})"><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M12 4v14m-5-5 5 5 5-5M5 21h14"/></svg> 回到最新</button></div><div ref="live" class="ac-live-text acr-live-text"><LiveTranscript presentation="recording" :parts="subtitleParts" :events="subtitles.events.value" :after-event-id="subtitles.ready.value?subtitles.cursor.value:null" :delayed="subtitles.delayed.value" @recover="subtitles.refresh()"/><div v-if="subtitles.error.value" class="ac-error" role="alert">{{subtitles.error.value}}<button class="btn sm" :disabled="subtitles.loading.value" @click="subtitles.refresh()">重试读取字幕</button></div></div><div class="acr-simulation-note">音频分片保存到服务端；未确认音频暂存本机，最多约十分钟，重连后补传。刷新、关闭或休眠会中断设备，恢复时开启新段；字幕延迟不影响音频保存。</div></section>
 <RecordingArchivePlayback v-if="finished&&native.record.value" :recording="native.record.value.session"/><RecordingTranscription v-if="finished&&meeting&&native.record.value" ref="recordingTranscriptionRef" :meeting-id="meeting" :session-id="native.record.value.session.sessionId" :can-mutate="!!session.current.value"/><LegacyRecordingFiles :meeting-id="meeting"/></div><div v-if="localDevelopment" class="demo-note">当前页面数据均为产品演示用模拟数据，不代表招商基金真实业务信息。<br>当前原型为纯前端交互演示，不连接招商基金真实业务系统。当前原型仅展示会议负责人的相关功能。</div></main></div></div><MeetingInfoDrawer :open="infoOpen" :prevent-close="infoEditorRef?.closeBlocked??false" @close="closeInfo"><MeetingInfoEditor ref="infoEditorRef" v-if="infoOpen&&meeting&&app.infoScopeReady.value" :meeting-id="meeting" :eligible="!finished" @close="infoOpen=false"/></MeetingInfoDrawer><dialog ref="materialsDialog" class="recording-material-dialog" aria-labelledby="recording-material-title" @cancel.prevent="closeMaterials"><header class="between"><h2 id="recording-material-title">会议背景材料</h2><button class="btn sm ghost" aria-label="关闭背景材料" :disabled="materialsState.closeBlocked" @click="closeMaterials">✕</button></header><div class="recording-material-body"><MaterialImportSection v-if="materialsOpen&&meeting" :meeting-id="meeting" @state="materialsState=$event"/><p v-if="materialsState.closeBlocked&&!materialsState.busy" class="small ac-error mt12" role="status">请先核对原材料请求，确认结果后再离开。</p></div><footer><button class="btn primary" :disabled="materialsState.closeBlocked" @click="closeMaterials">完成</button></footer></dialog>
 <dialog ref="interruptDialog" class="recording-decision-mask mask" role="presentation" @cancel.self.prevent="closeDecision(interruptDialog)" @click.self="closeDecision(interruptDialog)"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="record-interrupt-title"><header class="modal-h"><h3 id="record-interrupt-title" class="m-t">中断本段录音</h3><button type="button" class="m-x" aria-label="关闭中断录音确认" :disabled="busy" @click="closeDecision(interruptDialog)"><Icon name="x" :size="18"/></button></header><div class="modal-b"><p>本段已确认音频将保留，未确认分片仍暂存本机；继续录音将开启新段。</p><p v-if="localError||r.error.value" role="alert">{{localError??r.error.value}}</p></div><footer class="modal-f"><button class="btn" :disabled="busy" @click="closeDecision(interruptDialog)">取消</button><button class="btn primary" :disabled="busy" @click="interrupt">保存本段</button></footer></section></dialog>
 <dialog ref="endDialog" class="recording-decision-mask mask" role="presentation" @cancel.self.prevent="closeDecision(endDialog)" @click.self="closeDecision(endDialog)"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="record-end-title"><header class="modal-h"><h3 id="record-end-title" class="m-t">结束录音</h3><button type="button" class="m-x" aria-label="关闭结束录音确认" :disabled="busy" @click="closeDecision(endDialog)"><Icon name="x" :size="18"/></button></header><div class="modal-b"><p>本次会议共{{parts.length}}段录音，累计{{clock(r.elapsed.value)}}。保存后可稍后继续处理，也可立即开始处理。</p><div class="small muted">所有录音段按顺序归属同一会议，无需重新上传。取消将返回当前暂停或中断状态，不自动恢复录音。</div><p v-if="busy" class="small muted mt12" role="status">正在确认原分片并提交归档，完成后可回听。</p><div class="ac-error small mt12" role="alert">{{endError??''}}</div></div><footer class="modal-f"><button class="btn" :disabled="busy" @click="closeDecision(endDialog)">取消</button><button v-if="endError&&lastEnd" class="btn primary" :disabled="busy" @click="finish(lastEnd)">重试保存</button><button class="btn" :disabled="busy||!!endError" @click="finish('save')">保存</button><button class="btn primary" aria-label="保存并开始转写" :disabled="busy||!!endError" @click="finish('process')">开始处理</button></footer></section></dialog>
</template>

<style scoped>.recording-material-dialog{margin:auto;width:min(1040px,calc(100vw - 32px));max-height:90dvh;padding:0;overflow:auto;border:1px solid var(--border);border-radius:10px;color:var(--text);background:white}.recording-material-dialog::backdrop{background:#11184955}.recording-material-dialog>header{padding:18px 24px;border-bottom:1px solid var(--border)}.recording-material-dialog h2{font-size:17px}.recording-material-body{padding:20px 24px}.recording-material-dialog>footer{position:sticky;bottom:0;display:flex;justify-content:flex-end;padding:14px 24px;border-top:1px solid var(--border);background:white}@media(max-width:700px){.recording-material-body{padding:16px}.recording-material-dialog>header{padding:16px}}</style>

<style scoped>.acr-page .ac-workspace-leading{gap:24px}.recording-decision-mask{inset:0;width:auto;height:auto;max-width:none;max-height:none;margin:0;padding:0;border:0;color:var(--text);overflow:visible}.recording-decision-mask:not([open]){display:none}.recording-decision-mask::backdrop{background:transparent}.recording-decision-mask>.modal{margin:0;padding:0}.recording-decision-mask .modal-b{min-height:0}.recording-decision-mask .modal-b [role=alert]{color:var(--red)}</style>

<style scoped>@media(max-width:650px){.acr-page .ac-workspace-leading{gap:10px}}</style>
